import {grammar,sets,closure,buildLR,parseLR,itemText,productionText,actionLabel} from './engine.js';
const samples={
 'LR(0)':[{name:'01 · Balanced pairs — LR(0)',grammar:'S -> C C\nC -> c C | d',input:'c d d'},{name:'02 · Single sequence — LR(0)',grammar:'S -> a A\nA -> b',input:'a b'},{name:'03 · Expressions — not LR(0)',grammar:'E -> E + T | T\nT -> T * F | F\nF -> ( E ) | id',input:'id + id * id'},{name:'04 · Ambiguous expressions — conflict',grammar:'E -> E + E | E * E | id',input:'id + id * id'}],
 'SLR(1)':[{name:'01 · Expressions — SLR(1)',grammar:'E -> E + T | T\nT -> T * F | F\nF -> ( E ) | id',input:'id + id * id'},{name:'02 · Nullable list — SLR(1)',grammar:'S -> a S | ε',input:'a a'},{name:'03 · Assignment — CLR(1), not SLR(1)',grammar:'S -> L = R | R\nL -> * R | id\nR -> L',input:'id = id'},{name:'04 · Ambiguous expressions — conflict',grammar:'E -> E + E | E * E | id',input:'id + id * id'}],
 'CLR(1)':[{name:'01 · Assignment — CLR(1)',grammar:'S -> L = R | R\nL -> * R | id\nR -> L',input:'id = id'},{name:'02 · Context-sensitive lookaheads — CLR(1)',grammar:'S -> a A d | b A e | a B e | b B d\nA -> c\nB -> c',input:'a c d'},{name:'03 · Ambiguous expressions — not CLR(1)',grammar:'E -> E + E | E * E | id',input:'id + id * id'}],
 'LALR(1)':[{name:'01 · Expressions — LALR(1)',grammar:'E -> E + T | T\nT -> T * F | F\nF -> ( E ) | id',input:'id + id * id'},{name:'02 · Assignment — LALR(1)',grammar:'S -> L = R | R\nL -> * R | id\nR -> L',input:'id = id'},{name:'03 · CLR(1), not LALR(1) — merge conflict',grammar:'S -> a A d | b A e | a B e | b B d\nA -> c\nB -> c',input:'a c d'},{name:'04 · Ambiguous expressions — conflict',grammar:'E -> E + E | E * E | id',input:'id + id * id'}],
};
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='parsing-lab-v1';let stored={};try{stored=JSON.parse(localStorage.getItem(key)||'{}')}catch{};
let page=['home','bottom','lr'].includes(stored.page)?stored.page:'home',type=samples[stored.type]?stored.type:'SLR(1)',sessions=stored.sessions||{},timer=null,error='',zoom=1,selected=null;
for(const t of Object.keys(sessions))if(!samples[t])delete sessions[t];
const cache=new Map();
function session(){if(!sessions[type])sessions[type]={...samples[type][0],sample:0,cursor:0,built:false,policy:'stop',traceInput:null};return sessions[type];}
function save(){try{localStorage.setItem(key,JSON.stringify({page,type,sessions}))}catch{$('.save-status').textContent='Storage unavailable';}}
function stop(){if(timer){clearInterval(timer);timer=null;}}
function isLR(){return ['LR(0)','SLR(1)','CLR(1)','LALR(1)'].includes(type);}
function model(){const s=session();if(!s.built)return null;const signature=type+'\n'+s.grammar;if(!cache.has(signature)){const g=grammar(s.grammar);cache.set(signature,buildLR(g,type));}return cache.get(signature);}
function allEvents(m){if(!m)return [];let events=m.events;if(session().traceInput!==null){const s=session(),signature=type+'\n'+s.grammar+'\n'+s.traceInput+'\n'+s.policy;const traceKey='trace:'+signature;if(!cache.has(traceKey))cache.set(traceKey,parseLR(m,s.traceInput,s.policy));events=[...events,...cache.get(traceKey).map(e=>({...e,states:m.states,edges:m.edges,table:m.table}))];}return events;}
function navigate(p,t){stop();page=p;if(t){type=t;selected=null;zoom=1;}error='';save();render();window.scrollTo({top:0,behavior:'smooth'});}
function bindNav(){document.querySelectorAll('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===page||page==='lr'&&b.dataset.page==='bottom');b.onclick=()=>navigate(b.dataset.page)});document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go,b.dataset.type));}
function home(){return `<div class="hero"><div><span class="eyebrow">From grammar to understanding</span><h1>Parsing /<br>Parsers<span style="color:#d27ba4">.</span></h1><p class="subtitle">A grammar is just the beginning. Explore how parsers make decisions, build their states, and recognise a string — one thoughtful step at a time.</p><button class="primary" data-go="lr" data-type="SLR(1)">Explore LR parsing ↗</button> <span class="status-pill">Interactive learning lab</span></div><div class="hero-art"><div class="section-label">A little grammar. A visible process.</div><svg viewBox="0 0 440 220" aria-label="Illustration of a parser moving between states"><defs><marker id="ha" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8" fill="#a25e89"/></marker></defs><path d="M125 105 H195 M285 105 H355" stroke="#a25e89" stroke-width="2" fill="none" marker-end="url(#ha)"/><path d="M245 143 V180 H83 V143" stroke="#61a18a" stroke-dasharray="5 4" stroke-width="2" fill="none" marker-end="url(#ha)"/><rect x="20" y="55" width="105" height="91" rx="16" fill="#fbe1ec" stroke="#e3adc7"/><rect x="195" y="55" width="90" height="91" rx="16" fill="#fff2ba" stroke="#e0c86f"/><rect x="355" y="55" width="70" height="91" rx="16" fill="#e0f3e9" stroke="#a7cbb9"/><g font-family="monospace" text-anchor="middle" fill="#774260"><text x="73" y="88" font-size="18">I₀</text><text x="73" y="115" font-size="11">S → • a A</text><text x="240" y="88" font-size="18">I₁</text><text x="240" y="115" font-size="11">S → a • A</text><text x="390" y="88" font-size="18">I₂</text><text x="390" y="115" font-size="11">accept</text><text x="160" y="92" font-size="12">a</text><text x="320" y="92" font-size="12">A</text></g><circle cx="155" cy="105" r="5" fill="#c35487"><animate attributeName="cx" values="135;180;135" dur="3s" repeatCount="indefinite"/></circle></svg><div class="mono" style="padding:12px;background:#fffcf3;border-radius:10px">Grammar → Item sets → Table → Parse</div></div></div><div class="path-cards lr-only"><article class="card path"><div class="icon" style="background:var(--yellow)">↑</div><span class="eyebrow">Build from the input</span><h2>Bottom-Up Parsing</h2><p>Shift symbols, discover handles, and reduce towards the start symbol. See every state, transition, and conflict as it happens.</p><div class="tags"><span class="tag">LR(0)</span><span class="tag">SLR(1)</span><span class="tag">CLR(1)</span><span class="tag">LALR(1)</span></div><button data-go="bottom">Explore bottom-up →</button></article></div><div class="intro-strip"><span><b>01</b> Enter your grammar</span><span><b>02</b> Construct step by step</span><span><b>03</b> Test a string</span><span>↶ Every step is reversible</span></div>`;}
function menu(){return `<div class="crumb"><a href="#home" data-go="home">Home</a> › <span>Bottom-Up Parsing</span></div><h1>Bottom-Up Parsing</h1><p class="subtitle">Follow the input from individual tokens to the start symbol. Choose an LR variant to open its interactive workspace.</p><div class="path-cards lr-only"><article class="card path"><div class="icon">{ }</div><h2>LR Parsing</h2><p>Build the canonical collection of item sets, create an ACTION/GOTO table, and trace shifts and reductions.</p><div class="variants">${['LR(0)','SLR(1)','CLR(1)','LALR(1)'].map(t=>`<button class="small" data-go="lr" data-type="${t}">${t}</button>`).join('')}</div><button class="pink" data-go="lr" data-type="${isLR()?type:'SLR(1)'}">Open LR workspace →</button></article></div>`;}
function editor(m,events,event){const s=session(),ph=event?.phase;return `<section class="card"><div class="editor-grid"><div><label for="sample">Sample grammar</label><select id="sample"><option value="custom" ${s.sample==='custom'?'selected':''}>Custom grammar</option>${samples[type].map((x,i)=>`<option value="${i}" ${s.sample===i?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div><label for="variant">Parser variant</label><select id="variant">${['LR(0)','SLR(1)','CLR(1)','LALR(1)'].map(t=>`<option ${t===type?'selected':''}>${t}</option>`).join('')}</select></div><div><label for="input">Test string · space-separated tokens</label><input id="input" value="${esc(s.input)}" placeholder="Leave empty to test ε" autocomplete="off"></div></div><label for="grammar">Grammar · one rule per line</label><textarea id="grammar" spellcheck="false">${esc(s.grammar)}</textarea><p class="help">Write <code>E -> E + T | T</code>. Separate all symbols with spaces. The first left-hand side is the start symbol. Use <code>ε</code> or <code>eps</code> for an empty production. Symbols defined on the left are nonterminals; everything else is a terminal. $ is added automatically.</p>${error?`<div class="error" role="alert">${esc(error)}</div>`:''}<div class="toolbar"><button id="build" class="pink">${s.built?'↻ Build / Reset':'Build parser ↗'}</button><button id="prev" class="yellow" ${!m||s.cursor===0?'disabled':''}>◀ Previous Step</button><button id="next" class="pink" ${!m||s.cursor>=events.length-1?'disabled':''}>Next Step ▶</button><button id="play" class="yellow" ${!m||s.cursor>=events.length-1?'disabled':''}>${timer?'Ⅱ Pause':'▷ Auto-play'}</button><button id="runall" class="yellow">Run Everything ⏩</button><span class="spacer"></span><button id="starttrace" ${!m||s.cursor<m.events.length-1?'disabled':''}>${s.traceInput===null?'Test string →':'Restart string trace ↻'}</button></div><div class="phasebar"><span class="phase ${ph==='collection'?'current':m?'done':''}">① Item sets</span><span class="phase ${ph==='table'?'current':ph==='parse'?'done':''}">② ACTION / GOTO</span><span class="phase ${ph==='parse'?'current':''}">③ String parsing</span><span class="counter mono">${m?`Step ${s.cursor+1} / ${events.length}${s.traceInput===null?' · construction':''}`:'Ready to build'}</span></div><div class="progress"><div style="width:${events.length?(s.cursor+1)/events.length*100:0}%"></div></div></section>`;}
function setTable(m){const g=m.g;return `<div class="two-cols"><div><h3 class="section-label">Augmented grammar</h3>${g.productions.map(p=>`<div class="production mono ${current()?.active?.item?.p===p.id?'current':''}"><span class="number">${p.id}</span>${esc(productionText(p))}</div>`).join('')}</div><div><h3 class="section-label">FIRST and FOLLOW</h3><div class="table-wrap"><table><thead><tr><th>Nonterminal</th><th>FIRST</th><th>FOLLOW</th></tr></thead><tbody>${[g.augmented,...g.nonterminals].map(n=>`<tr><td>${esc(n)}</td><td>{ ${esc([...m.sets.first[n]].join(', '))} }</td><td>{ ${esc([...m.sets.follow[n]].join(', '))} }</td></tr>`).join('')}</tbody></table></div><details><summary>Why these sets matter</summary>FIRST describes the tokens that can begin a derivation; FOLLOW describes tokens that can appear after a nonterminal. SLR reductions use FOLLOW. CLR closure computes FIRST(βa), where β is the suffix after a nonterminal and a is the inherited lookahead.</details></div></div>`;}
let currentEvent=null;const current=()=>currentEvent;
function groupedItems(items){const groups=new Map();for(const i of items){const k=i.p+':'+i.dot;if(!groups.has(k))groups.set(k,{...i,las:[]});if(i.la!==undefined)groups.get(k).las.push(i.la);}return [...groups.values()];}
function graph(m,e){
 const states=e.states??[],edges=e.edges??[];
 // Use the complete topology to keep every box fixed while revealing snapshots.
 const merged=states[0]?.mergedFrom!==undefined;
 const layoutStates=type==='LALR(1)'&&!merged?m.canonical:m.states;
 // The canonical pre-merge edges are available on the last non-merged snapshot.
 const topology=type==='LALR(1)'&&!merged?m.events.findLast(ev=>ev.phase==='collection'&&!ev.active?.merged)?.edges??edges:m.edges;
 const levels=new Map([[0,0]]),queue=[0];
 for(let k=0;k<queue.length;k++)for(const ed of topology.filter(ed=>ed.from===queue[k]))if(!levels.has(ed.to)){levels.set(ed.to,levels.get(ed.from)+1);queue.push(ed.to);}
 for(const st of layoutStates)if(!levels.has(st.id))levels.set(st.id,0);
 const nw=214,rowHeight=17,colGap=144,verticalGap=57;
 const rowsFor=st=>groupedItems(st.items).flatMap(i=>{
  let text=itemText(m.g,{p:i.p,dot:i.dot});if(i.las.length)text+=' , { '+i.las.join(', ')+' }';
  const rows=[];while(text.length>30){let cut=text.lastIndexOf(' ',30);if(cut<12)cut=30;rows.push({text:text.slice(0,cut),item:i,continued:rows.length>0});text=text.slice(cut).trim();}rows.push({text,item:i,continued:rows.length>0});return rows;
 });
 const fullRows=new Map(layoutStates.map(st=>[st.id,rowsFor(st)]));
 const longReturns=topology.filter(ed=>(levels.get(ed.from)??0)-(levels.get(ed.to)??0)>1);
 const topMargin=55+longReturns.length*16,coords=new Map(),heights=new Map(),columns=new Map();
 for(const st of layoutStates){const depth=levels.get(st.id);if(!columns.has(depth))columns.set(depth,[]);columns.get(depth).push(st);}
 let height=0;for(const [depth,column] of columns){let y=topMargin;for(const st of column){const h=36+fullRows.get(st.id).length*rowHeight;coords.set(st.id,{x:52+depth*(nw+colGap),y});heights.set(st.id,h);y+=h+verticalGap;}height=Math.max(height,y);}
 const width=104+(Math.max(0,...columns.keys())+1)*nw+Math.max(0,...columns.keys())*colGap;
 height=Math.max(240,height+16);
 const ports=new Map();
 const side=ed=>ed.from===ed.to?['top','top']:(levels.get(ed.to)>levels.get(ed.from)?['right','left']:levels.get(ed.to)<levels.get(ed.from)?['left','right']:['left','left']);
 topology.forEach((ed,j)=>{const [a,b]=side(ed);for(const [id,suffix,part] of [[ed.from,a,'out'],[ed.to,b,'in']]){const key=id+':'+suffix;if(!ports.has(key))ports.set(key,[]);ports.get(key).push({j,part});}});
 const port=(id,side,j,part)=>{const c=coords.get(id),h=heights.get(id),list=ports.get(id+':'+side)??[],rank=list.findIndex(p=>p.j===j&&p.part===part);return {x:side==='left'?c.x:side==='right'?c.x+nw:c.x+(rank+1)*nw/(list.length+1),y:side==='top'?c.y:c.y+27+(rank+1)*(h-35)/(list.length+1)};};
 const labelAt=(a,b,c,d,t)=>{const u=1-t;return {x:u*u*u*a.x+3*u*u*t*b.x+3*u*t*t*c.x+t*t*t*d.x,y:u*u*u*a.y+3*u*u*t*b.y+3*u*t*t*c.y+t*t*t*d.y};};
 const paths=edges.map((ed,j)=>{
  const a=coords.get(ed.from),b=coords.get(ed.to);if(!a||!b)return '';
  const canonicalIndex=topology.findIndex(t=>t.from===ed.from&&t.to===ed.to&&t.symbol===ed.symbol);
  const index=canonicalIndex<0?j:canonicalIndex,[fromSide,toSide]=side(ed),p=port(ed.from,fromSide,index,'out'),q=port(ed.to,toSide,index,'in');
  let path,label;
  if(ed.from===ed.to){const siblings=topology.filter(t=>t.from===ed.from&&t.to===ed.to),rank=siblings.findIndex(t=>t.symbol===ed.symbol),lift=33+rank*11;path=`M ${p.x} ${p.y} C ${p.x-24} ${p.y-lift} ${q.x+24} ${q.y-lift} ${q.x} ${q.y}`;label={x:(p.x+q.x)/2,y:p.y-lift+5};}
  else if((levels.get(ed.from)??0)-(levels.get(ed.to)??0)>1){const rank=longReturns.findIndex(t=>t.from===ed.from&&t.to===ed.to&&t.symbol===ed.symbol),topY=22+rank*16,ra=a.x-25-rank*4,rb=b.x+nw+25+rank*4;path=`M ${p.x} ${p.y} C ${ra} ${p.y} ${ra} ${topY+22} ${ra} ${topY} C ${ra-24} ${topY} ${rb+24} ${topY} ${rb} ${topY} C ${rb} ${topY+22} ${rb} ${q.y} ${q.x} ${q.y}`;label={x:(ra+rb)/2,y:topY-6};}
  else if(levels.get(ed.from)===levels.get(ed.to)){
   const siblings=topology.filter(t=>t.from!==t.to&&levels.get(t.from)===levels.get(t.to)&&levels.get(t.from)===levels.get(ed.from)),rank=siblings.findIndex(t=>t.from===ed.from&&t.to===ed.to&&t.symbol===ed.symbol),bend=35+rank*9,rail=Math.max(14,a.x-Math.min(colGap-20,bend));const c={x:rail,y:p.y},d={x:rail,y:q.y};path=`M ${p.x} ${p.y} C ${c.x} ${c.y} ${d.x} ${d.y} ${q.x} ${q.y}`;label=labelAt(p,c,d,q,.5);label.x-=8;
  }else{
   const sign=fromSide==='right'?1:-1,distance=Math.abs(q.x-p.x),bend=Math.max(45,distance*.5),c={x:p.x+sign*bend,y:p.y},d={x:q.x-sign*bend,y:q.y};path=`M ${p.x} ${p.y} C ${c.x} ${c.y} ${d.x} ${d.y} ${q.x} ${q.y}`;label=labelAt(p,c,d,q,.46);label.y-=5;
  }
  const nt=m.g.nonterminals.includes(ed.symbol),active=e.active?.edge===j;
  return `<path class="edge ${nt?'nt':''} ${active?'active':''}" data-transition="${ed.from}-${ed.to}-${esc(ed.symbol)}" d="${path}" marker-end="url(#${active?'book-arrow-active':nt?'book-arrow-nt':'book-arrow'})"/><text class="edge-label" x="${label.x}" y="${label.y}" text-anchor="middle">${esc(ed.symbol)}</text>`;
 }).join('');
 const nodes=states.map(st=>{
  const c=coords.get(st.id);if(!c)return '';const rows=rowsFor(st),h=heights.get(st.id),origin=m.origins[st.id];
  const originText=st.mergedFrom?'merge '+st.mergedFrom.map(i=>'I'+i).join(', '):origin?.from===null?'start':origin?`goto(I${origin.from}, ${origin.symbol})`:'';
  const conflict=e.phase!=='collection'&&m.conflicts.some(cf=>cf.state===st.id),accept=st.items.some(i=>i.p===0&&i.dot===m.g.productions[0].rhs.length);
  const firstClosureRow=rows.findIndex(r=>!st.kernel?.some(k=>k.p===r.item.p&&k.dot===r.item.dot));
  return `<g class="state-node book-state ${e.active?.state===st.id||e.active?.merge?.includes(st.id)?'active':''} ${selected===st.id?'selected':''} ${conflict?'conflicted':''} ${accept?'accepting':''}" data-state="${st.id}" tabindex="0" role="button" aria-label="State ${st.mergedFrom?'M':'I'}${st.id}, show derivation" transform="translate(${c.x},${c.y})"><rect class="node-box" width="${nw}" height="${h}" rx="7"/><text class="book-state-title" x="10" y="17">${st.mergedFrom?'M':'I'}${st.id}${conflict?' ⚠':''}</text><text class="book-origin" x="${nw-10}" y="17" text-anchor="end">${esc(originText.length>26?originText.slice(0,24)+'…':originText)}</text>${firstClosureRow>0?`<line x1="8" x2="${nw-8}" y1="${26+firstClosureRow*rowHeight}" y2="${26+firstClosureRow*rowHeight}" stroke="#c7e1ef"/>`:''}${rows.map((r,j)=>{
   const active=e.active?.item&&r.item.p===e.active.item.p&&r.item.dot===e.active.item.dot,kernel=st.kernel?.some(k=>k.p===r.item.p&&k.dot===r.item.dot),complete=r.item.dot===m.g.productions[r.item.p].rhs.length;
   const text=esc(r.text).replaceAll('•','<tspan fill="#c9578c">•</tspan>');
   return `${active?`<rect x="5" y="${25+j*rowHeight}" width="${nw-10}" height="16" rx="3" fill="#fff0a4"/>`:''}<text x="${r.continued?19:10}" y="${37+j*rowHeight}" style="font-weight:${kernel?'700':'400'};${complete?'fill:#b26b2f':''}">${text}</text>`;
  }).join('')}</g>`;
 }).join('');
 return `<section class="card"><div class="section-head"><h2>01 · Item-set diagram</h2><div><button class="small" id="zoomout" aria-label="Zoom out">−</button> <button class="small" id="zoomreset">${Math.round(zoom*100)}%</button> <button class="small" id="zoomin" aria-label="Zoom in">+</button> <button class="small" id="zoomfit">Fit diagram</button> <button class="small" id="focus">Focus active state</button></div></div><div class="legend"><span><i></i> terminal transition</span><span><i class="nt"></i> nonterminal transition</span><span><i class="focus"></i> current operation</span><span><b>Bold</b> kernel item · click a state for its derivation</span></div><div class="diagram-viewport book-diagram" id="graph"><svg width="${width*zoom}" height="${height*zoom}" viewBox="0 0 ${width} ${height}" aria-label="Textbook-style LR item-set automaton"><defs><filter id="book-shadow" x="-20%" y="-20%" width="140%" height="140%"><feDropShadow dx="0" dy="2" stdDeviation="3" flood-color="#759bad" flood-opacity=".15"/></filter>${[['book-arrow','#a88cc6'],['book-arrow-nt','#55ad91'],['book-arrow-active','#bd4c83']].map(([id,color])=>`<marker id="${id}" markerWidth="9" markerHeight="9" refX="8" refY="4.5" orient="auto" markerUnits="userSpaceOnUse"><path d="M0 0L9 4.5L0 9Z" fill="${color}"/></marker>`).join('')}</defs>${paths}${nodes}</svg>${!states.length?'<div class="empty">Build the grammar to reveal the first state.</div>':''}</div>${derivation(m,e)}${type==='LALR(1)'?'<p class="help">CLR states are shown first. Merge steps highlight identical cores; final M-states union their lookaheads.</p>':''}<p class="help">Textbook layout: states follow goto depth from left to right. Curved arrows show transitions and self-loops; dashed arrows represent nonterminals.</p></section>`;
}

function derivation(m,e){if(selected===null)return '';const st=e.states?.find(x=>x.id===selected);if(!st)return '';const ids=st.mergedFrom??[st.id];return `<div class="derivation"><h3>${st.mergedFrom?'Merged state M':'State I'}${st.id} · derivation</h3>${ids.map(id=>{const o=(st.mergedFrom?m.canonicalOrigins:m.origins)[id];if(!o)return '';return `<p><b>I${id}:</b> ${o.from===null?'Initial augmented start item':`GOTO(I${o.from}, ${esc(o.symbol)}): move the dot across ${esc(o.symbol)} in matching source items`}.</p><div class="mono">${o.seed.map(i=>esc(itemText(m.g,i))).join('<br>')}</div>${o.additions.filter(a=>st.items.some(i=>i.p===a.next.p&&i.dot===a.next.dot&&i.la===a.next.la)).map(a=>`<p>↳ ${esc(itemText(m.g,a.from))}<br>adds <b class="mono">${esc(itemText(m.g,a.next))}</b>${a.next.la!==undefined?` using FIRST(β ${esc(a.from.la)}).`:''}</p>`).join('')}`;}).join('')}</div>`;}
function parsingTable(m,e){
 const columns=[...m.g.terminals,'$',...m.g.nonterminals],table=e.table??(e.phase==='parse'?m.table:{});
 const cells=m.states.map(row=>`<tr><th>${type==='LALR(1)'&&e.states?.[0]?.mergedFrom?'M':'I'}${row.id}</th>${columns.map(col=>{const key=`${row.id}|${col}`,actions=table[key]??[];return `<td class="${actions.length>1?'conflict-cell':''} ${e.active?.cell===key?'active-cell':''}" data-cell="${esc(key)}" tabindex="${actions.length?'0':'-1'}" title="${actions.length?'Click for the source of this entry':'Not filled yet'}">${actions.length?esc(actions.map(actionLabel).join(' / ')):'·'}${actions.length>1?' ⚠':''}</td>`;}).join('')}</tr>`).join('');
 const done=e.phase==='parse'||session().cursor>=m.events.length-1;
 return `<section class="card"><div class="section-head"><h2>02 · ACTION / GOTO table</h2><span class="status-pill">${done?'Construction complete':'Revealing one entry at a time'}</span></div><p class="phase-intro">Shift sN → push state N · Reduce rN → use production N · accept → complete. Select a filled cell to inspect its source item.</p><div class="table-wrap"><table><thead><tr><th rowspan="2">State</th><th colspan="${m.g.terminals.length+1}">ACTION · terminals</th><th colspan="${m.g.nonterminals.length}">GOTO · nonterminals</th></tr><tr>${columns.map(t=>`<th>${esc(t)}</th>`).join('')}</tr></thead><tbody>${cells}</tbody></table></div><div id="cellsource"></div>${done?`<div class="verdict ${m.conflicts.length?'bad':''}">${m.conflicts.length?`⚠ This grammar is not ${esc(type)}. Conflicts: ${m.conflicts.map(c=>`I${c.state} / ${esc(c.symbol)} — ${c.type}`).join('; ')}`:`✓ This grammar is ${esc(type)}: no table conflicts.`}</div>`:''}</section>`;
}
function trace(m,events,e){const trace=events.slice(m.events.length,session().cursor+1);return `<section class="card"><div class="section-head"><h2>03 · String parsing</h2><span class="status-pill" style="${e.status==='accept'?'':e.status!=='running'?'background:#ffe0ec;color:#903052':''}">${e.status==='running'?'In progress':e.status==='conflict'?'REJECT · unresolved conflict':e.status?.toUpperCase()}</span></div><div class="tokens" aria-label="Remaining input"><span class="section-label" style="padding:9px 0">Input</span>${e.input.map((t,i)=>`<span class="token ${i===0?'current':''}">${esc(t)}</span>`).join('')}</div><div class="trace-layout"><div><h3 class="section-label">Stack · top highlighted</h3><div class="stack-box">${e.stack.map(x=>`<div class="stack-item">${esc(x)}</div>`).join('')}</div></div><div class="table-wrap"><table class="trace-table"><thead><tr><th>#</th><th>Stack</th><th>Input</th><th>Action · resulting state</th></tr></thead><tbody>${trace.map((s,i)=>`<tr class="${i===trace.length-1?'current':''}"><td>${i}</td><td>${esc(s.stack.join(' '))}</td><td>${esc(s.input.join(' '))}</td><td>${esc(s.message)}</td></tr>`).join('')}</tbody></table></div></div></section>`;}
function workspace(){let m=null,events=[],e=null;try{m=model();events=allEvents(m);if(m){session().cursor=Math.max(0,Math.min(session().cursor,events.length-1));e=events[session().cursor];}}catch(err){error=err.message;session().built=false;session().traceInput=null;save();}currentEvent=e;return `<div class="crumb"><a href="#home" data-go="home">Home</a> › <a href="#bottom" data-go="bottom">Bottom-Up Parsing</a> › <span>LR Parsing</span></div><h1>Interactive LR Parser Builder</h1><p class="subtitle">Build ${type} one step at a time: item sets, the ACTION/GOTO table, then a parse of your string.</p>${editor(m,events,e)}${isLR()?`<details class="card" style="margin-top:0"><summary>What makes ${type} different?</summary>${type==='LR(0)'?'Items carry no lookahead. Each completed item reduces on all terminals, so many useful grammars have conflicts.':type==='SLR(1)'?'Build LR(0) item sets, then place reductions only on the FOLLOW set of the completed production’s left-hand side.':type==='CLR(1)'?'Items carry a lookahead. Closure propagates FIRST(βa), and reductions are restricted to the completed item’s own lookahead.':'First build CLR(1), then merge states with identical LR(0) cores, unioning lookaheads. This can introduce reduce-reduce conflicts even when CLR(1) has none.'}</details>`:''}${m?`<div class="explain ${e.status==='conflict'||e.message.includes('CONFLICT')?'conflict':e.status==='accept'?'accept':''}" role="status" aria-live="polite"><span class="pointer">${e.active?.backtrack?'↶':'➜'}</span><span>${esc(e.message)}</span></div><section class="card">${setTable(m)}</section>${isLR()?graph(m,e):''}${e.phase!=='collection'?parsingTable(m,e):''}${isLR()?`<section class="card"><h3>Conflict behaviour</h3><p class="phase-intro">A conflicted table cannot choose a unique action. Default: reject the deterministic parse at the encountered cell. For an experiment, select an explicit policy; acceptance then applies to that chosen path and does not make the grammar ${type}.</p><label for="policy">When the trace encounters multiple actions</label><select id="policy"><option value="stop" ${session().policy==='stop'?'selected':''}>Stop at conflict · no arbitrary choice</option><option value="shift" ${session().policy==='shift'?'selected':''}>Explore one path · prefer shift, then lowest rN</option><option value="reduce" ${session().policy==='reduce'?'selected':''}>Explore one path · prefer lowest-numbered reduction</option></select></section>`:''}${e.phase==='parse'?trace(m,events,e):`<section class="card"><h2>03 · String parsing</h2><p class="phase-intro">Finish construction with Next Step, then select Test string. Each shift, reduction, or match will appear individually. Previous Step restores the exact earlier stack, input pointer, table and diagram.</p></section>`}`:`<section class="card"><div class="empty"><h2>Every parser starts with a grammar.</h2>Select an example or write your own, then click Build parser.<br>The first item appears immediately. You control everything after that.</div></section>`}`;}
function render(){const oldDock=document.querySelector('.step-dock');if(oldDock)oldDock.remove();const viewport=$('#graph'),scroll=viewport?{left:viewport.scrollLeft,top:viewport.scrollTop}:null;$('#app').innerHTML=page==='home'?home():page==='bottom'?menu():workspace();bindNav();if(['lr'].includes(page)){bindWorkspace();if(session().built&&currentEvent){const events=allEvents(model());const dock=document.createElement('div');dock.className='step-dock';dock.innerHTML=`<span class="dock-message">${esc(currentEvent.message)}</span><span class="dock-count mono">${session().cursor+1} / ${events.length}</span><button id="dockprev" class="yellow" ${session().cursor===0?'disabled':''}>◀ Previous</button><button id="docknext" class="pink" ${session().cursor>=events.length-1?'disabled':''}>Next Step ▶</button><button id="dockrunall" class="yellow">Run Everything ⏩</button>`;document.body.append(dock);$('#dockprev').onclick=()=>{stop();step(-1)};$('#docknext').onclick=()=>{stop();step(1)};$('#dockrunall').onclick=runEverything;}}if(scroll&&$('#graph')){$('#graph').scrollLeft=scroll.left;$('#graph').scrollTop=scroll.top;}}
function step(delta){const m=model(),events=allEvents(m);session().cursor=Math.max(0,Math.min(events.length-1,session().cursor+delta));if(session().cursor>=events.length-1)stop();save();render();}
function runEverything(){
 stop();error='';selected=null;const s=session();s.built=true;s.traceInput=null;s.cursor=0;
 try{
  const m=model();s.cursor=m.events.length-1;s.traceInput=s.input;
  try{s.cursor=allEvents(m).length-1;}catch(err){s.traceInput=null;throw err;}
 }catch(err){error=err.message;if(s.cursor===0)s.built=false;}
 save();render();
}
function bindWorkspace(){const s=session();$('#runall').onclick=runEverything;$('#grammar').oninput=e=>{s.grammar=e.target.value;s.sample='custom';s.built=false;s.traceInput=null;s.cursor=0;stop();error='';save();$('#sample').value='custom';$('#next').disabled=true;$('#prev').disabled=true;$('#starttrace').disabled=true;$('#play').disabled=true;document.querySelector('.step-dock')?.remove();if($('.explain'))$('.explain').textContent='Grammar changed. Build the parser or select Run Everything to use this grammar.';};$('#grammar').onchange=()=>{};$('#input').oninput=e=>{s.input=e.target.value;save();};$('#sample').onchange=e=>{if(e.target.value==='custom')return;sessions[type]={...samples[type][+e.target.value],sample:+e.target.value,cursor:0,built:false,policy:s.policy,traceInput:null};stop();error='';selected=null;save();render();};$('#variant').onchange=e=>{type=e.target.value;stop();selected=null;error='';save();render();};$('#build').onclick=()=>{stop();error='';selected=null;s.cursor=0;s.traceInput=null;s.built=true;try{model();}catch(e){error=e.message;s.built=false;}save();render();};$('#prev').onclick=()=>{stop();step(-1)};$('#next').onclick=()=>{stop();step(1)};$('#play').onclick=()=>{if(timer){stop();render();return;}timer=setInterval(()=>{try{step(1)}catch(e){stop();error=e.message;render();}},1100);render();};$('#starttrace').onclick=()=>{stop();error='';try{const m=model();const old=s.traceInput;s.traceInput=s.input;try{allEvents(m);}catch(e){s.traceInput=old;throw e;}s.cursor=m.events.length;save();}catch(e){error=e.message;}render();};if($('#policy'))$('#policy').onchange=e=>{stop();s.policy=e.target.value;if(s.traceInput!==null)s.cursor=model().events.length;save();render();};
 if($('#zoomin')){$('#zoomin').onclick=()=>{zoom=Math.min(1.8,zoom+.15);render();};$('#zoomout').onclick=()=>{zoom=Math.max(.4,zoom-.15);render();};$('#zoomreset').onclick=()=>{zoom=1;render();};$('#zoomfit').onclick=()=>{const svg=$('#graph svg');zoom=Math.max(.25,Math.min(1.8,($('#graph').clientWidth-14)/svg.viewBox.baseVal.width));render();};$('#focus').onclick=()=>{const target=$(`[data-state="${current()?.active?.state??0}"]`);target?.scrollIntoView({block:'nearest',inline:'center',behavior:'smooth'});};document.querySelectorAll('[data-state]').forEach(n=>{const act=()=>{selected=+n.dataset.state;render()};n.onclick=act;n.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();act();}};});}
 document.querySelectorAll('[data-cell]').forEach(el=>{const act=()=>{const m=model(),e=current(),actions=(e.table??m.table)[el.dataset.cell]??[];if(!actions.length)return;$('#cellsource').innerHTML=`<div class="derivation"><h3>Source for [${esc(el.dataset.cell.replace('|',', '))}]</h3>${actions.map(a=>`<p><b>${esc(actionLabel(a))}</b> · ${esc(a.reason)}</p><p class="mono">${esc(itemText(m.g,a.item))}</p>`).join('')}</div>`;};el.onclick=act;el.onkeydown=e=>{if(e.key==='Enter')act();};});}
window.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(!['lr'].includes(page)||!session().built)return;if(e.key==='ArrowRight'){e.preventDefault();stop();step(1);}if(e.key==='ArrowLeft'){e.preventDefault();stop();step(-1);}});
window.addEventListener('hashchange',()=>{if(['home','bottom'].includes(location.hash.slice(1)))navigate(location.hash.slice(1));});
render();
